// Pega todos os itens que a LLM gerou
const items = $input.all();

// Pega os itens da tabela de clientes usando o nome EXATO do nó que vimos no print
const clientesTabela = $("Converte resultado  em tabela para LLM").all();

return items.map((itemObj, index) => {
  const item = itemObj.json;

  // Pega o cliente correspondente na tabela pelo número da linha (index)
  const cliente = clientesTabela[index]?.json ?? {};

  // 1. Extrai o texto da OpenAI
  const textoGerado = item.output?.[0]?.content?.[0]?.text
                   ?? item.content?.[0]?.text
                   ?? item.message?.content
                   ?? item.text
                   ?? "";

  // 2. Extrai o Assunto e o Corpo
  let assunto = "Oportunidade de Investimento Personalizada";
  let corpoTexto = textoGerado;

  const matchAssunto = textoGerado.match(/Assunto:\s*(.+)/i);
  if (matchAssunto) {
    assunto = matchAssunto[1].trim();
    corpoTexto = textoGerado.replace(/Assunto:\s*.+(\r?\n)+/i, "").trim();
  }

  const corpoHtml = corpoTexto.replace(/\n/g, "<br>");

  return {
    json: {
      to: cliente.email || "",
      nome: cliente.nome || "",
      subject: assunto,
      messageText: corpoTexto,
      messageHtml: corpoHtml
    }
  };
});

// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : json.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // normaliza minimo para numero
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

