// Pega os dados que vieram do nó anterior
const item = $input.first().json;

// Pega a lista de recomendações (ou lista vazia se não encontrar)
const lista = item.recomendacoes ?? [];

// Transforma cada cliente em um item individual (formato de tabela do n8n)
return lista.map(cliente => {
  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      produtoSugerido: cliente.produtoSugerido,
      rentabilidade: cliente.rentabilidade,
      mensagemBase: cliente.mensagem
    }
  };
});

// 1. Pega os clientes e os investimentos que vieram do Merge
const dados = $input.first().json;
const clientes = dados.body?.clientes ?? dados.clientes ?? [];
const investimentos = dados.investimentos ?? [];

// 2. Para cada cliente, vamos encontrar o investimento ideal e montar a mensagem
const recomendacoes = clientes.map(cliente => {
  // Procura um investimento que tenha o mesmo perfil do cliente
  const investimentoRecomendado = investimentos.find(
    inv => inv.perfil?.toLowerCase() === cliente.perfil?.toLowerCase()
  );

  const produto = investimentoRecomendado?.produto ?? "Investimento Diversificado";
  const rentabilidade = investimentoRecomendado?.rentabilidade ?? "Consulte nossos especialistas";

  // Monta a mensagem personalizada
  const mensagem = `Olá, ${cliente.nome}! Identificamos que o seu perfil de investidor é ${cliente.perfil}. Com base no seu saldo de ${cliente.saldo}, recomendamos a aplicação em "${produto}" (Rentabilidade estimada: ${rentabilidade}).`;

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo: cliente.saldo,
    produtoSugerido: produto,
    rentabilidade: rentabilidade,
    mensagem: mensagem
  };
});

// 3. Retorna a lista no formato que o n8n e o Respond to Webhook esperam
return [{ json: { recomendacoes } }];
